dashboard.definition:
{
  "title": "Cost Analysis",
  "description": "Lookup-driven spend tracking with unpriced-model visibility",
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "inputs": {
    "input_timerange": {
      "type": "input.timerange",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@d,now"
      },
      "title": "Time Range"
    },
    "input_model": {
      "type": "input.dropdown",
      "title": "Model",
      "dataSources": {
        "primary": "ds_model_options"
      },
      "options": {
        "defaultValue": "*",
        "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
        "token": "model_tok"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "formattedStatics": ">statics | formatByType(formattedConfig)",
        "statics": [
          ["All"],
          ["*"]
        ],
        "label": ">primary | seriesByName(\"model\") | renameSeries(\"label\") | formatByType(formattedConfig)",
        "value": ">primary | seriesByName(\"model\") | renameSeries(\"value\") | formatByType(formattedConfig)"
      }
    }
  },
  "dataSources": {
    "ds_model_options": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | stats count by model | sort - count | fields model"
      },
      "name": "Model Options"
    },
    "ds_base_daily": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | search model=$model_tok|s$ | timechart span=1d sum(cost_usd) as daily_cost, count as messages, sum(eval(if(pricing_known=\"false\",1,0))) as unpriced_msgs"
      },
      "name": "Base: Daily Cost"
    },
    "ds_kpi_total": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_daily",
        "query": "| stats sum(daily_cost) as count | eval count=\"$\".tostring(round(count,2),\"commas\") | fields count"
      },
      "name": "KPI Total Cost"
    },
    "ds_kpi_daily_avg": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_daily",
        "query": "| stats avg(daily_cost) as count | eval count=\"$\".tostring(round(count,2),\"commas\") | fields count"
      },
      "name": "KPI Daily Average"
    },
    "ds_kpi_cost_per_msg": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_daily",
        "query": "| stats sum(daily_cost) as c, sum(messages) as m | eval count=if(m>0, \"$\".round(c/m,4), \"n/a\") | fields count"
      },
      "name": "KPI Cost per Message"
    },
    "ds_kpi_unpriced": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_daily",
        "query": "| stats sum(unpriced_msgs) as count | fields count"
      },
      "name": "KPI Unpriced Messages"
    },
    "ds_daily_trend": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_daily",
        "query": "| fields _time, daily_cost | rename daily_cost as \"Daily Cost (USD)\""
      },
      "name": "Daily Cost Trend"
    },
    "ds_cumulative": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_daily",
        "query": "| streamstats sum(daily_cost) as cumulative | eval cumulative=round(cumulative,2) | fields _time, cumulative | rename cumulative as \"Cumulative Cost (USD)\""
      },
      "name": "Cumulative Cost"
    },
    "ds_base_model": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | search model=$model_tok|s$ | stats sum(cost_usd) as cost, count as messages by model, pricing_known"
      },
      "name": "Base: Cost by Model"
    },
    "ds_model_pie": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_model",
        "query": "| stats sum(cost) as cost by model | sort - cost | eval cost=round(cost,2)"
      },
      "name": "Cost by Model"
    },
    "ds_unknown_models": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_model",
        "query": "| where pricing_known=\"false\" | stats sum(messages) as Messages by model | sort - Messages | rename model as \"Unpriced Model\""
      },
      "name": "Unpriced Models"
    },
    "ds_base_session": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | search model=$model_tok|s$ | stats sum(cost_usd) as cost, count as messages, sum(total_tokens) as tokens, latest(cwd) as project by sessionId"
      },
      "name": "Base: Cost by Session"
    },
    "ds_kpi_max_session": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_session",
        "query": "| stats max(cost) as count | eval count=\"$\".round(count,2) | fields count"
      },
      "name": "KPI Most Expensive Session"
    },
    "ds_session_table": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_session",
        "query": "| eval cost=round(cost,4) | sort - cost | head 25 | rename sessionId as \"Session ID\", cost as \"Cost (USD)\", messages as \"Messages\", tokens as \"Total Tokens\", project as \"Project\""
      },
      "name": "Top Sessions by Cost"
    },
    "ds_project_cost": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_session",
        "query": "| where isnotnull(project) | stats sum(cost) as cost by project | sort - cost | head 15 | eval cost=round(cost,2) | rename project as \"Project\", cost as \"Cost (USD)\""
      },
      "name": "Cost by Project"
    }
  },
  "visualizations": {
    "viz_kpi_total": {
      "type": "splunk.singlevalue",
      "title": "Total Cost",
      "dataSources": {
        "primary": "ds_kpi_total"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_daily_avg": {
      "type": "splunk.singlevalue",
      "title": "Daily Avg",
      "dataSources": {
        "primary": "ds_kpi_daily_avg"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_cost_per_msg": {
      "type": "splunk.singlevalue",
      "title": "Cost/Message",
      "dataSources": {
        "primary": "ds_kpi_cost_per_msg"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_max_session": {
      "type": "splunk.singlevalue",
      "title": "Most Expensive Session",
      "dataSources": {
        "primary": "ds_kpi_max_session"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_unpriced": {
      "type": "splunk.singlevalue",
      "title": "Unpriced Messages",
      "dataSources": {
        "primary": "ds_kpi_unpriced"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)",
        "majorColor": "> majorValue | rangeValue(unpricedColors)"
      },
      "context": {
        "unpricedColors": [
          {"value": "#118832", "to": 1},
          {"value": "#D41F1F", "from": 1}
        ]
      }
    },
    "viz_daily_trend": {
      "type": "splunk.area",
      "title": "Daily Cost Trend",
      "dataSources": {
        "primary": "ds_daily_trend"
      },
      "options": {}
    },
    "viz_cumulative": {
      "type": "splunk.line",
      "title": "Cumulative Cost",
      "dataSources": {
        "primary": "ds_cumulative"
      },
      "options": {}
    },
    "viz_model_pie": {
      "type": "splunk.pie",
      "title": "Cost by Model",
      "dataSources": {
        "primary": "ds_model_pie"
      },
      "options": {}
    },
    "viz_project_bar": {
      "type": "splunk.bar",
      "title": "Cost by Project",
      "dataSources": {
        "primary": "ds_project_cost"
      },
      "options": {}
    },
    "viz_unpriced_models": {
      "type": "splunk.table",
      "title": "Unpriced Models",
      "dataSources": {
        "primary": "ds_unknown_models"
      },
      "options": {}
    },
    "viz_session_table": {
      "type": "splunk.table",
      "title": "Top Sessions by Cost",
      "dataSources": {
        "primary": "ds_session_table"
      },
      "options": {},
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "VisiCore_App_for_AI_Observability",
            "dashboard": "sessions",
            "tokens": [
              {
                "token": "form.session_tok",
                "value": "row.Session ID.value"
              }
            ]
          }
        }
      ]
    }
  },
  "layout": {
    "type": "grid",
    "options": {},
    "structure": [
      {"item": "viz_kpi_total", "type": "block", "position": {"x": 0, "y": 0, "w": 240, "h": 120}},
      {"item": "viz_kpi_daily_avg", "type": "block", "position": {"x": 240, "y": 0, "w": 240, "h": 120}},
      {"item": "viz_kpi_cost_per_msg", "type": "block", "position": {"x": 480, "y": 0, "w": 240, "h": 120}},
      {"item": "viz_kpi_max_session", "type": "block", "position": {"x": 720, "y": 0, "w": 240, "h": 120}},
      {"item": "viz_kpi_unpriced", "type": "block", "position": {"x": 960, "y": 0, "w": 240, "h": 120}},
      {"item": "viz_daily_trend", "type": "block", "position": {"x": 0, "y": 120, "w": 600, "h": 300}},
      {"item": "viz_cumulative", "type": "block", "position": {"x": 600, "y": 120, "w": 600, "h": 300}},
      {"item": "viz_model_pie", "type": "block", "position": {"x": 0, "y": 420, "w": 400, "h": 300}},
      {"item": "viz_project_bar", "type": "block", "position": {"x": 400, "y": 420, "w": 400, "h": 300}},
      {"item": "viz_unpriced_models", "type": "block", "position": {"x": 800, "y": 420, "w": 400, "h": 300}},
      {"item": "viz_session_table", "type": "block", "position": {"x": 0, "y": 720, "w": 1200, "h": 320}}
    ],
    "globalInputs": ["input_timerange", "input_model"]
  }
}
